# bank3.map — local label renames and comments for bank3.s
#
# Directives:
#   RENAME  <old>  <new>    ; optional comment
#   COMMENT <label> <text>   ; inserts "; text" before label definition
#
# Labels sourced from original_source/src/*.ROU (PDS bank 14)
# Applied by: python3 annotate.py src/bank3_raw.s info/bank3.map src/bank3.s
#
# Naming convention:
#   PDS numeric locals !1 !2 etc  →  @n1 @n2 etc
#   PDS named locals !done !fly   →  @done @fly etc
#   PDS dotted locals !T3.2       →  @t3_2 etc
#
# ---------------------------------------------------------------------------
# SECTION banners — inserted before the first label of each source file
# ---------------------------------------------------------------------------

SECTION  times16lo         TIMINGS.ROU
SECTION  cm_reset          START.ROU
SECTION  anewgame          MAINLOOP.ROU
SECTION  cm_nmi            INTERUPT.ROU
SECTION  resetrobinvars    CONTROL.ROU
SECTION  putextrason       XTRACONT.ROU
SECTION  flashblock        XTRAROUS.ROU
SECTION  checkaddflamesetc ONSCREEN.ROU
SECTION  spritetable       SPRITESD.DAT
SECTION  printspriterev    SPRITESR.ROU
SECTION  prtmessagefly     PRTMESS.ROU
SECTION  compactedchrstable UNPACK.ROU
SECTION  readkeypads       GENERAL.ROU
SECTION  attributemasks    MAPSCROL.ROU
SECTION  changebank_n1     ENDCODE.ROU

# ---------------------------------------------------------------------------
# TIMINGS.ROU
# ---------------------------------------------------------------------------

INLINE  C1F6  entry: A = strip number

# ---------------------------------------------------------------------------
# Macro replacements — data tables replaced with computed ca65 equivalents
# ---------------------------------------------------------------------------

REPLACE  C01A  C0F1  macros/times16lo.inc
REPLACE  C0F2  C0FF  macros/times32tablelo.inc
REPLACE  C100  C10D  macros/times32tablehi.inc
REPLACE  C11E  C1F5  macros/times16hi.inc
REPLACE  CCC9  CCF8  macros/runtablelo.inc
REPLACE  F72B  F82A  macros/times14tablelo.inc
REPLACE  F82B  F92A  macros/times14tablehi.inc

# ---------------------------------------------------------------------------
# SPRITESD.DAT — sprite pointer table (66 entries) + definitions
# Format: count, {control, [x, y,] chrlo, chrhi | chrnum}...
# Control bits: %vhxyPPPP — v=vflip, h=hflip, x=has displacement, y=chr pointer mode, P=palette
# ---------------------------------------------------------------------------

INLINE  E8DB  spritetable: 66 word pointers to sprite definitions
INLINE  E95F  --- titlelogos group ---
INLINE  E9D9  --- robinheads group (4 frames) ---
INLINE  E9ED  --- robinbodies group (7 frames) ---
INLINE  EA30  --- bodyfiring group (standing + 4 fire frames) ---
INLINE  EA8A  --- legsrunning group (7 frames) ---
INLINE  EAE5  --- morelegs group (standing, jumping, crouch, ladder) ---
INLINE  EB31  --- barrels group (3 rotation frames) ---
INLINE  EB64  --- canon + platform ---
INLINE  EB70  --- trampoline group (2 frames) ---
INLINE  EB8A  --- spider group (2 frames) ---
INLINE  EBA6  --- bat group (2 frames) ---
INLINE  EBBC  --- shared chr blocks (coin, canon, platform) ---
INLINE  EBC6  --- deadarrow group (4 distance frames) ---
INLINE  EC0A  --- eyes group (4 frames) ---
INLINE  EC2E  --- guard group (low/high fire + recoil) ---
INLINE  EC7A  --- fire group (5 frames) ---
INLINE  ECBB  --- marion ---
INLINE  ECD8  --- pause sprite ---
INLINE  C200  entry: A = strip number

# bank_table entries 12–15: mapper write values for each switchable bank
RENAME  LC016  banksel12    ; bank_table[12] = $0C → selects bank0.bin at $8000
RENAME  LC017  banksel13    ; bank_table[13] = $0D → selects bank1.bin at $8000
RENAME  LC018  banksel14    ; bank_table[14] = $0E → selects bank2.bin at $8000
RENAME  LC019  banksel15    ; bank_table[15] = $0F

# emptyblockbuffer locals: !2 !4
RENAME  LC226  @n2      ; !2 lda blockbuffer,x
RENAME  LC273  @n4      ; !4 rts

# ---------------------------------------------------------------------------
# START.ROU — cm_reset / lock chip / pastlock
# ---------------------------------------------------------------------------

# lock chip: LOCK1 mid-instruction equate and locals
RENAME  LC295  lock1        ; PDS LOCK1 — mid-instruction equate (*+1): bne lock1 loop re-entry
RENAME  LC2B6  @n1          ; !1 dec $72 (ghfh scope: bcs @n1 counter decrement path)
RENAME  LC2CF  @n1          ; !1 lda LC2DA,y (pastlock scope: bne @n1 copy loop start)

# ---------------------------------------------------------------------------
# MAINLOOP.ROU — startup / anewgame / ingameloop
# ---------------------------------------------------------------------------

# clearram loop
RENAME  LC319  @n1      ; !1 sta (address),y  — clearram inner loop
RENAME  LC31E  @n2      ; !2 inc $1C          — clearram page loop

# anewgame flybackvar wait
RENAME  LC35B  @fly     ; flybackvar inner bpl loop in anewgame

# ingameloop flybackvar wait
RENAME  LC39D  @fly     ; flybackvar inner bpl loop in ingameloop

# ingameloop: !5 = odd-frame path (jsr changebank13rou first)
# Must be global: LC402:=*+1 and LC406:=*+2 equates sit between the bne ref (C3FF) and this def (C413)
RENAME  LC413  ingameloop_n5 ; !5 jsr changebank13rou (ingameloop: odd-frame path — global; LC402/LC406 break scope)

# zoominstars: !1 = early return rts
RENAME  LC492  @n1      ; !1 rts (zoominstars: bcc/bne early return)

# ingameloop: !11 = skip zoominstars
RENAME  LC3B1  @n11     ; !11 lda pause (ingameloop: skip zoominstars call)

# ingameloop: scope break fix — LC3CA sits between refs and defs of @n21/@n12
# make LC3CA a cheap local so it doesn't reset the scope
RENAME  LC3CA  @pause_y ; pause-Y adjust branch (only used at bcs LC3CA within ingameloop)
# ingameloop: pause screen layout jmp via !21 → endofmainloop
RENAME  LC3D1  @n21     ; !21 jmp endofmainloop (pause: bne !21)
RENAME  LC3D4  @n12     ; !12 jsr doorrou       (ingameloop: beq !12)

# nearendofmainloop: killed handling
RENAME  LC436  @n7      ; !7  lda pause         (nearendofmainloop killed path)
RENAME  LC451  @n5      ; !5  lda fadecounter   (nearendofmainloop common rts path)

# resetrobinvars1 / bob1 sequence
RENAME  LC5B1  @n21     ; !21 lda #$05 (resetrobinvars1: tune check skip)

# infinate lives loop
RENAME  LC602  @n6      ; !6  lda #$03 sta hearts inx (infinate: lives loop body)

# bob1 lives display
RENAME  LC60D  @n1      ; !1  cpx #$00 (bob1: lower bound check)
RENAME  LC616  @n12     ; !12 ldy #<life1mess (bob1: prtmessage index)
RENAME  LC621  @n2      ; !2  tax jsr prtmessage (bob1: bcc !2)

# copyintreasures
RENAME  LC645  @n7      ; !7  iny (copyintreasures: bne !7)

# resetrobinvars1 completedgame display
RENAME  LC663  @n3      ; !3  jsr changebank12rou (completedgame: beq !3)

# post-reset display wait loop
RENAME  LC675  @n11     ; !11 jsr turninteron (bmi !11)
RENAME  LC678  @n1      ; !1  asl flyflag — outer flybackvar restart
RENAME  LC67A  @fly     ; flybackvar inner bpl in lives display loop

# display-loop branch targets
RENAME  LC6A0  @n8      ; !8  jsr changebank13rou (lda completedgame beq !8)
RENAME  LC6AE  @n6      ; !6  lda pad (display wait loop)

# ---------------------------------------------------------------------------
# INTERUPT.ROU — cm_nmi / interupt / dontdointerupt / setfade / allblack
# ---------------------------------------------------------------------------

# interupt locals: !1 !4
RENAME  LC4B2  @n1      ; !1 jsr emptyblockbuffer (interupt: bne @n1 skips fade+printbuffer)
RENAME  LC4D1  @n4      ; !4 jsr dointerpause (interupt: bne @n4 skips sendspriteblock)

# dontdointerupt locals: !1
RENAME  LC4F5  @n1      ; !1 pla (dontdointerupt: bne @n1 skips music playback)

# setfade locals: !1
RENAME  LC51B  @n1      ; !1 lda (address),y (setfade: bne @n1 colour copy loop)

# allblack: flybackvar wait loop
RENAME  LC56E  @fly     ; flybackvar inner bpl loop in allblack

