RENAME  LC7B7  @n3      ; !3  inc robiny (bne !3 / jmp !3)
RENAME  LC7FF  @n1      ; !1  rts (fallthru: various bne/beq !1)

# ontopofladder
RENAME  LC81A  @n1      ; !1  rts (ontopofladder: bne !1)

# checkleftrightkeys
RENAME  LC832  @n1      ; !1  lda pad / and #lmask (beq !1)
RENAME  LC83D  @n3      ; !3  cmp oleftright (bne !3)
RENAME  LC847  @n4      ; !4  sta oleftright (beq !4)
RENAME  LC84A  @n2      ; !2  rts (checkleftrightkeys: robincrouch bne !2)

# onladder
RENAME  LC87A  @n14     ; !14 dec robinxl (onladder: bcs !14)
RENAME  LC87D  @bug     ; !bug ldy robiny (onladder: centering jmp !bug)
RENAME  LC8A1  @bugok   ; !bugok jmp LC8FF (onladder: beq !bugok)
RENAME  LC8A4  @n13     ; !13 jsr checkleftrightkeys (onladder: centred)
RENAME  LC8D8  onladder_n3 ; !3  lda pad (onladder: beq !3 right-side check — global; LC8C3 breaks scope)
RENAME  LC8EC  @n22     ; !22 lda robiny (onladder: beq !22 jump-right skip)
RENAME  LC8FF  onladder_n4 ; !4  jsr checkifstillonladderup (onladder: final path — global; LC8C3 breaks scope)
# LC8C3 itself is NOT renamed — it has no PDS local label number (it is the amask check inside the
# left-wall block, and its only non-garbled reference is the fall-through from above); it also
# serves as a data address referenced by ldx LC8C3,y in XTRACONT garbled data at $CCEF.
RENAME  LC90E  @n2      ; !2  rts (checkifstillonladderup: beq !2)

# checkifstillonladderdown locals: !1
RENAME  LC93E  @n1      ; !1 rts (checkifstillonladderdown: bcc/beq early return)

# checkifstillonladderup
RENAME  LC9B3  @n1      ; !1  lda pad (checkifstillonladderup: beq/beq !1)
RENAME  LC9BC  @n2      ; !2  rts (bne !2 / rts)

# checkforladderdown
RENAME  LC9E4  @n1      ; !1  lda robinjumping (bne !1)
RENAME  LC9EE  @n2      ; !2  rts (bne !2)

# docrouchstuff
RENAME  LCA47  @n6      ; !6  lda counter (docrouchstuff: bne !6)
