RENAME  LCB7B  @n8      ; !8  jsr restorex1 jmp !2 (dogravity)
RENAME  LCB81  @n6      ; !6  lda #0 sta robinjumping (dogravity landed)
RENAME  LCB9A  @n5      ; !5  lda #$80 sta robingravity (dogravity: bcc !5)
RENAME  LCB9F  @n1      ; !1  rts (dogravity: bmi / bcc)

# dorobinjumping
RENAME  LCBAC  @bugwashere ; !bugwashere lda robincrouch
RENAME  LCBB5  @n3      ; !3  jsr addleftright (dorobinjumping: beq !3)
RENAME  LCBD1  @n2      ; !2  jsr findroof (dorobinjumping: beq !2)
RENAME  LCBDC  @n1      ; !1  lda runcount (dorobinjumping: bpl !1)

# addleftright
RENAME  LCC2E  @n2      ; !2  lda runcount (addleftright: beq !2 / bne !2)
RENAME  LCC3E  @n8      ; !8  lda counter (addleftright: bne !8)
RENAME  LCC4D  @n11     ; !11 ldy #$01 (addleftright: bne !11)
RENAME  LCC54  @n9      ; !9  lda oleftright (addleftright: bne !9)
RENAME  LCC6F  @n5      ; !5  rts (addleftright: bcc !5)
RENAME  LCC70  @n4      ; !4  sty temp (addleftright: negative path)
RENAME  LCC8A  @n8b     ; !8  lda robinxh (addleftright: bcs !8b — check overflow)
RENAME  LCCC5  @n17     ; !17 jmp restorex (addleftright: bne !17)
RENAME  LCCC8  @n7      ; !7  rts (addleftright: bcc !7)

# findwallleft / restwall
# # LCD30 stays global (runtablelo data decodes bvc LCD30). This breaks @n2/@n3 in restwall:
# so LCD34/LCD37 must also be global.
#RENAME  LCD30  @n1      ; !1  cmp #$03 (findwallleft: return 1 path)
RENAME  LCD34  restwall_n2 ; !2  lda #$01 rts (findwallleft: wall found — global; LCD30 breaks scope)
RENAME  LCD37  restwall_n3 ; !3  lda #$00 rts (findwallleft: no wall — global; LCD30 breaks scope)

# findfloor
RENAME  LCD59  @n3      ; !3  jsr findsolid (findfloor: bcs !3)
RENAME  LCD6F  @n4      ; !4  jsr findsolid (findfloor: bcc !4)
RENAME  LCD7A  @n6      ; !6  sta solidfound (findfloor: bcs !6)
RENAME  LCD8E  @n2      ; !2  lda #$00 (findfloor: bne !2)
RENAME  LCD90  @n1      ; !1  rts (findfloor: bne !1)

# findroof
RENAME  LCD9D  @n2      ; !2  rts (findroof: beq !2)
RENAME  LCDAB  @n1      ; !1  jsr findsolid (findroofleft: bcs !1)
RENAME  LCDBE  @n2      ; !2  jsr findsolid (findroofright: bcc !2)

# movebackcrouchedunder
RENAME  LCDE6  @n1      ; !1  jmp setcrouch (movebackcrouchedunder: bne !1 then jmp)
RENAME  LCDE9  @n2      ; !2  lda #$06 (LCDE9 = after !1 block)
RENAME  LCDFE  @n3      ; !3  pla jmp setcrouch (slidebackright: bne !3)
RENAME  LCE1E  @n4      ; !4  pla jmp setcrouch (slidingneg bne path)
RENAME  LCE22  @n5      ; !5  lda #$FA findroofleft (slidingneg: bne !5)

# checkrobinbehind
RENAME  LCE8A  @n1      ; !1  lda runcount (checkrobinbehind: beq !1)
RENAME  LCE94  @n4      ; !4  ldx #$20 (checkrobinbehind: beq !4)
RENAME  LCE96  @n2      ; !2  stx spritebehind (checkrobinbehind: bcs/bcc)

# putextrason / anotherrou / backfromrou
RENAME  LCED7  @n1      ; !1  jmp anotherrou (putextrason: bcc !1)

# maprouspointer and routinepointers hi-byte table columns
# (PDS uses lda maprouspointer+1,x / lda routinepointers+1,x — da65 creates labels at +1)
RENAME  LCEFB  maprouspointer_hi  ; maprouspointer+1: hi-byte column of map routine address pairs
RENAME  LCF15  routinepointers_hi ; routinepointers+1: hi-byte column of routine address pairs

# LCF36 is a DATA position (in routinepointers table, bytes decoded as bmi target) — skip

# endofrous: wait loop for extravars overflow
# All endofrous locals must be global because endofrous_n2/endofrous_n3 (maprouspointer data refs)
# sit inside endofrous: scope and break cheap-local visibility for the whole function.
RENAME  LCEE1  endofrous_n1 ; !1  php pha (endofrous: wait loop entry)
RENAME  LCEE5  endofrous_n2 ; !2  and #$1E (endofrous: inner wait — global; ref from maprouspointer data)
RENAME  LCEF6  endofrous_n3 ; !3  jmp !1 (endofrous inner loop — global; ref from maprouspointer data)
RENAME  LCEF9  endofrous_n4 ; !4  rts (endofrous: bcc !4)

